"""Lossless stdlib compressor. Usage: compress.py [--decompress] input output."""
import bz2
import sys
from pathlib import Path


def compress(data):
    return bz2.compress(data, compresslevel=9)


def decompress(data):
    return bz2.decompress(data)


if __name__ == '__main__':
    args = sys.argv[1:]
    decode = args and args[0] == '--decompress'
    if decode:
        args = args[1:]
    if len(args) != 2:
        raise SystemExit('usage: compress.py [--decompress] input output')
    Path(args[1]).write_bytes((decompress if decode else compress)(Path(args[0]).read_bytes()))

"""Repeat round trips to make the correctness assay substantial."""
from pathlib import Path
import time
import compress


def main():
    original = Path('corpus_hard.txt').read_bytes()
    deadline = time.perf_counter() + 0.5
    while True:
        packed = compress.compress(original)
        if compress.decompress(packed) != original:
            print(0)
            return
        if time.perf_counter() >= deadline:
            break
    Path('out.bin').write_bytes(packed)
    Path('restored.txt').write_bytes(compress.decompress(packed))
    print(100 * (1 - len(packed) / len(original)))


if __name__ == '__main__':
    try:
        main()
    except Exception:
        print(0)

